SELECT m.* FROM memory_entry m
WHERE m.tenant_id = #{tenantId}
AND m.user_id = #{userId}
ORDER BY m.decay_weight ASC, m.last_accessed_at ASC, m.created_at ASC LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT m.* FROM memory_entry m
WHERE m.tier = 'SHORT_TERM'
AND m.decay_weight >= #{minDecayWeight}
AND m.access_count >= #{minAccessCount}
AND (m.expires_at IS NULL OR m.expires_at > #{now})
ORDER BY m.decay_weight DESC, m.access_count DESC, m.last_accessed_at DESC LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT COALESCE(SUM(m.source_content_length), 0)
FROM memory_entry m
WHERE m.tenant_id = #{tenantId}
AND m.user_id = #{userId}

SELECT COALESCE(SUM(m.stored_content_length), 0)
FROM memory_entry m
WHERE m.tenant_id = #{tenantId}
AND m.user_id = #{userId}

SELECT m.* FROM memory_entry m
WHERE m.expires_at IS NOT NULL
AND m.expires_at <= #{now}
ORDER BY m.expires_at ASC LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}
